/**
 * Seed flashcards from hand-curated pedagogos + audio bank + autogenerated
 * section-recall and cloze cards.
 *
 *   pnpm run seed
 */
import * as fs from 'node:fs';
import * as path from 'node:path';
import { createClient } from '@supabase/supabase-js';
import dotenv from 'dotenv';
dotenv.config({ path: path.join(process.cwd(), '.env.local') });

const sb = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!, {
  auth: { persistSession: false },
});

type CardRow = {
  type: string;
  front: string;
  back: string;
  hint?: string | null;
  tema_id?: number | null;
  section_id?: number | null;
  metadata?: Record<string, unknown> | null;
};

async function wipeCards() {
  const { error } = await sb.from('cards').delete().neq('id', -1);
  if (error) throw error;
}

function pedagogoCards(): CardRow[] {
  const raw = JSON.parse(fs.readFileSync(path.join(process.cwd(), 'data', 'pedagogos.json'), 'utf-8'));
  const cards: CardRow[] = [];

  for (const p of raw.pedagogos as any[]) {
    const temaId = (p.aparece_en_temas as number[])[0] ?? 7;

    // Author → method
    cards.push({
      type: 'author_method',
      front: `¿Cuál es el método asociado a **${p.nombre}**?`,
      back: `${p.metodo}\n\n**Principios clave:**\n- ${p.principios.join('\n- ')}`,
      hint: p.pais,
      tema_id: temaId,
      metadata: { pedagogo_id: p.id },
    });

    // Method → author
    cards.push({
      type: 'method_author',
      front: `¿Qué pedagogo/a creó el método **${p.metodo}**?`,
      back: `${p.nombre} (${p.pais}, ${p.anios})`,
      tema_id: temaId,
      metadata: { pedagogo_id: p.id },
    });

    // Keyword → author
    for (const kw of (p.palabras_clave as string[])) {
      cards.push({
        type: 'method_author',
        front: `¿Qué pedagogía trabaja con **${kw}**?`,
        back: `${p.nombre} — ${p.metodo}`,
        tema_id: temaId,
        metadata: { pedagogo_id: p.id, keyword: kw },
      });
    }

    // Quotes → author
    for (const cita of (p.citas as string[])) {
      cards.push({
        type: 'quote_author',
        front: `¿Quién dijo (o se le atribuye)?\n\n> "${cita}"`,
        back: `${p.nombre}`,
        tema_id: temaId,
        metadata: { pedagogo_id: p.id },
      });
    }
  }

  return cards;
}

function audioCards(): CardRow[] {
  const raw = JSON.parse(fs.readFileSync(path.join(process.cwd(), 'data', 'audio-bank.json'), 'utf-8'));
  const cards: CardRow[] = [];

  for (const iv of raw.intervalos as any[]) {
    cards.push({
      type: 'audio_interval',
      front: `Identifica el intervalo`,
      back: iv.nombre,
      hint: iv.ejemplo,
      tema_id: 2,
      metadata: { interval_id: iv.id, semitonos: iv.semitonos, choices: raw.intervalos.map((x: any) => x.nombre) },
    });
  }

  for (const modo of raw.modos as any[]) {
    cards.push({
      type: 'audio_mode',
      front: `Identifica el modo / escala`,
      back: modo.nombre,
      tema_id: 2,
      metadata: { mode_id: modo.id, intervals: modo.intervalos, choices: raw.modos.map((x: any) => x.nombre) },
    });
  }

  for (const tex of raw.texturas as any[]) {
    cards.push({
      type: 'audio_texture',
      front: `Identifica la textura`,
      back: tex.nombre,
      hint: tex.definicion,
      tema_id: 5,
      metadata: { texture_id: tex.id, voces: tex.voces, choices: raw.texturas.map((x: any) => x.nombre) },
    });
  }

  return cards;
}

function textureDefinitionCards(): CardRow[] {
  const raw = JSON.parse(fs.readFileSync(path.join(process.cwd(), 'data', 'audio-bank.json'), 'utf-8'));
  const cards: CardRow[] = [];
  for (const tex of raw.texturas as any[]) {
    cards.push({
      type: 'definition',
      front: `Define: **${tex.nombre}**`,
      back: tex.definicion,
      tema_id: 5,
    });
  }
  for (const f of raw.formas as any[]) {
    cards.push({
      type: 'definition',
      front: `Define la forma: **${f.nombre}**`,
      back: f.descripcion,
      tema_id: 5,
    });
  }
  for (const n of raw.normativa as any[]) {
    cards.push({
      type: 'law',
      front: `¿Qué es la **${n.nombre}**?`,
      back: `${n.full}\n\n${n.contexto}`,
      tema_id: 1,
    });
  }
  return cards;
}

async function sectionRecallCards(): Promise<CardRow[]> {
  const { data: temas } = await sb.from('temas').select('id, full_title');
  const cards: CardRow[] = [];
  for (const tema of temas ?? []) {
    const { data: topLevel } = await sb
      .from('sections')
      .select('number, title, level')
      .eq('tema_id', tema.id)
      .eq('level', 1)
      .order('order_idx');
    if (!topLevel || topLevel.length === 0) continue;

    const outline = topLevel
      .map((s: any) => `${s.number}. ${s.title}`)
      .join('\n');

    cards.push({
      type: 'section_recall',
      front: `Enumera las secciones principales del **TEMA ${tema.id}**.`,
      back: outline,
      tema_id: tema.id,
    });
  }
  return cards;
}

function curatedClozeCards(): CardRow[] {
  // Hand-crafted cloze cards targeting things worth memorizing exactly:
  // pedagogue associations, texture/form definitions, legal citations,
  // method keywords. One correct answer per blank.
  type C = { prompt: string; answer: string; tema: number };
  const C: C[] = [
    // --- Pedagogos (Tema 7) ---
    { tema: 7, answer: 'Dalcroze',    prompt: 'La **rítmica ____** se basa en la vivencia corporal del ritmo antes de su representación teórica.' },
    { tema: 7, answer: 'euritmia',    prompt: 'Los tres pilares del método Dalcroze son: ____, solfeo y la improvisación.' },
    { tema: 7, answer: 'Kodály',      prompt: 'El método ____ utiliza la solfa relativa (do móvil) y la fononimia.' },
    { tema: 7, answer: 'fononimia',   prompt: 'En el método Kodály, la ____ asocia a cada nota un gesto manual.' },
    { tema: 7, answer: 'ta',          prompt: 'Las sílabas rítmicas Kodály son ____ (negra) y ti-ti (dos corcheas).' },
    { tema: 7, answer: 'Orff',        prompt: 'El instrumental ____ está compuesto por xilófonos, metalófonos y carillones.' },
    { tema: 7, answer: 'ostinato',    prompt: 'Carl Orff basa gran parte de su propuesta en el ____ rítmico y melódico.' },
    { tema: 7, answer: 'Willems',     prompt: 'Para Edgar ____, el ritmo corresponde a la vida fisiológica, la melodía a la afectiva y la armonía a la mental.' },
    { tema: 7, answer: 'Martenot',    prompt: 'El método ____ parte de la alegría y la relajación como principios pedagógicos.' },
    { tema: 7, answer: 'gregoriano',  prompt: 'El método Ward se apoya en el canto ____ como base de la educación vocal.' },
    { tema: 7, answer: 'Suzuki',      prompt: 'El método ____ propone aprender la música como se aprende la lengua materna.' },
    { tema: 7, answer: 'Elizalde',    prompt: 'En España, Luis ____ adapta el método Ward al cancionero infantil español.' },
    { tema: 7, answer: 'Montessori',  prompt: 'Las campanillas ____ son materiales autocorrectivos para la educación sensorial del oído.' },
    { tema: 7, answer: 'dactilorritmia', prompt: 'Maurice Chevais emplea la ____, un sistema de gestos manuales para marcar el ritmo.' },
    { tema: 7, answer: 'paisaje',     prompt: 'R. Murray Schafer introduce la noción de ____ sonoro (soundscape) en la educación musical.' },
    { tema: 7, answer: 'musicograma', prompt: 'Jos Wuytack desarrolla el ____, un gráfico que permite la audición activa de una obra.' },
    { tema: 7, answer: 'numerofonía', prompt: 'Sergio Aschero propone la ____, un sistema notacional alternativo con números y colores.' },
    { tema: 7, answer: 'BAPNE',       prompt: 'El método ____ (Romero Naranjo) integra Biomecánica, Anatomía, Psicología, Neurociencia y Etnomusicología a través de la percusión corporal.' },

    // --- Texturas (Tema 5) ---
    { tema: 5, answer: 'monodia',     prompt: 'La ____ o monofonía es una única línea melódica sin acompañamiento (p. ej., canto gregoriano).' },
    { tema: 5, answer: 'homofonía',   prompt: 'En la ____, todas las voces se mueven con ritmo similar sobre una melodía principal.' },
    { tema: 5, answer: 'contrapunto', prompt: 'La polifonía se construye mediante el ____, es decir, la combinación de líneas melódicas independientes.' },
    { tema: 5, answer: 'acompañada',  prompt: 'En la melodía ____, una voz lleva el canto mientras las demás realizan funciones de acompañamiento.' },

    // --- Formas (Tema 5) ---
    { tema: 5, answer: 'rondó',       prompt: 'El ____ alterna un tema principal A con episodios contrastantes: ABACA…' },
    { tema: 5, answer: 'sonata',      prompt: 'La forma ____ consta de exposición, desarrollo y reexposición.' },
    { tema: 5, answer: 'fuga',        prompt: 'La ____ es una forma contrapuntística basada en la imitación de un sujeto.' },
    { tema: 5, answer: 'lied',        prompt: 'El ____ es una canción culta para voz y piano, cultivada especialmente en el Romanticismo.' },
    { tema: 5, answer: 'ternaria',    prompt: 'La forma ____ se representa con el esquema ABA: exposición, contraste y retorno.' },

    // --- Ritmo (Tema 6) ---
    { tema: 6, answer: 'libre',       prompt: 'El ritmo ____ no está sujeto a pulsación regular; aparece en el canto gregoriano o el recitativo.' },
    { tema: 6, answer: 'métrico',     prompt: 'El ritmo ____ organiza los pulsos en compases regulares.' },
    { tema: 6, answer: 'polirritmia', prompt: 'La superposición de dos o más esquemas rítmicos distintos se denomina ____.' },
    { tema: 6, answer: 'corporal',    prompt: 'La percusión ____ del método BAPNE utiliza el cuerpo como instrumento rítmico.' },

    // --- Melodía / Tonalidad (Tema 2) ---
    { tema: 2, answer: 'intervalo',   prompt: 'Un ____ es la distancia en altura entre dos sonidos.' },
    { tema: 2, answer: 'tonalidad',   prompt: 'La ____ es el sistema de relaciones jerárquicas entre notas en torno a una tónica.' },
    { tema: 2, answer: 'modalidad',   prompt: 'La ____ se refiere al carácter mayor o menor de una tonalidad.' },
    { tema: 2, answer: 'armadura',    prompt: 'La ____ indica al inicio del pentagrama los sostenidos o bemoles de la tonalidad.' },
    { tema: 2, answer: 'transporte',  prompt: 'El ____ consiste en escribir o interpretar una canción en una tonalidad distinta manteniendo su estructura intervalica.' },
    { tema: 2, answer: 'frase',       prompt: 'La ____ melódica es la unidad de sentido musical, análoga a la oración en el lenguaje verbal.' },

    // --- Lenguaje musical (Tema 1) ---
    { tema: 1, answer: 'LOMLOE',      prompt: 'La ____ (Ley Orgánica 3/2020) es la ley educativa vigente en España tras modificar la LOE.' },
    { tema: 1, answer: 'competencias', prompt: 'El currículo LOMLOE se articula en torno a ____ clave y situaciones de aprendizaje.' },
    { tema: 1, answer: '157',         prompt: 'El Real Decreto ____ /2022 establece las enseñanzas mínimas de Educación Primaria.' },
    { tema: 1, answer: 'Artística',   prompt: 'La Música forma parte del área de Educación ____, junto con la Educación Plástica y Visual.' },
    { tema: 1, answer: 'globalizador', prompt: 'El carácter ____ de la música permite integrarla con otras áreas curriculares en situaciones de aprendizaje.' },

    // --- Desarrollo (Tema 8) ---
    { tema: 8, answer: 'Piaget',      prompt: 'La psicogénesis del desarrollo de ____ organiza el aprendizaje en estadios sensoriomotor, preoperacional, operaciones concretas y formales.' },
    { tema: 8, answer: 'Vygotsky',    prompt: 'La zona de desarrollo próximo es una aportación de Lev ____ al constructivismo social.' },
    { tema: 8, answer: 'Bruner',      prompt: 'El aprendizaje por descubrimiento y el currículo en espiral son conceptos de Jerome ____.' },
    { tema: 8, answer: 'Ausubel',     prompt: 'David ____ es el principal teórico del aprendizaje significativo.' },
    { tema: 8, answer: 'Gardner',     prompt: 'Howard ____ postula la teoría de las inteligencias múltiples, entre ellas la inteligencia musical.' },
  ];

  return C.map((c) => ({
    type: 'cloze',
    front: `**TEMA ${c.tema}** — completa:\n\n${c.prompt.replace('____', '**____**')}`,
    back: c.answer,
    tema_id: c.tema,
  }));
}

async function main() {
  console.log('Seeding cards…');
  await wipeCards();

  const batches: CardRow[][] = [];
  batches.push(pedagogoCards());
  batches.push(audioCards());
  batches.push(textureDefinitionCards());
  batches.push(await sectionRecallCards());
  batches.push(curatedClozeCards());

  const all = batches.flat();
  console.log(`  Generated ${all.length} cards`);

  // Insert in chunks of 200
  for (let i = 0; i < all.length; i += 200) {
    const chunk = all.slice(i, i + 200).map((c) => ({
      ...c,
      metadata: c.metadata ? c.metadata : null,
    }));
    const { data, error } = await sb.from('cards').insert(chunk).select('id');
    if (error) {
      console.error('  insert error:', error.message);
      process.exit(1);
    }
    // Seed card_state (due now)
    const states = (data ?? []).map((r: any) => ({
      card_id: r.id,
      due_at: new Date().toISOString(),
    }));
    if (states.length > 0) {
      const { error: stErr } = await sb.from('card_state').insert(states);
      if (stErr) {
        console.error('  card_state insert error:', stErr.message);
        process.exit(1);
      }
    }
  }

  console.log('Done.');
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
